fn invalid(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,message)}
fn header<T>()->RetirementDemand{RetirementDemand{copy_bytes:2*size_of::<T>(),depth:1,..Default::default()}}
fn moved(d:RetirementDemand)->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,released_bytes:d.release_bytes}}
fn fits(cx:&StepContext<'_>,d:RetirementDemand)->bool{crate::registry::fits(cx.retained_grant(),d)}
fn physical(d:RetirementDemand)->OriginalConstructionDemand{OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth}}
/// 🏗️ Closes one effect-shaped cursor inside the context's own performed-work effect.
fn retire(cx:&mut StepContext<'_>,d:RetirementDemand,advance:impl FnOnce(&mut RetainedAllocationEffect<'_>)->OriginalRetirementPoll)->Result<(),OriginalTurnFailure>{close_original_effect_step(cx,d,advance).map(|_|())}
fn settle_step(effect:&mut RetainedAllocationEffect<'_>,result:Result<RetainedCloneStep,ValueError>)->OriginalRetirementPoll{RetirementPollExit::settle(effect,result.map_err(RetirementPollExit::from))}
fn retire_unit(cx:&mut StepContext<'_>,d:RetirementDemand,run:impl FnOnce()->Result<(),ValueError>)->Result<(),OriginalTurnFailure>{retire(cx,d,|effect|settle_step(effect,run().map(|()|RetainedCloneStep::Progress(moved(d)))))}
fn grant_close(cx:&mut StepContext<'_>,d:RetirementDemand,advance:impl FnOnce(RetainedCloneGrant)->RetainedWorkOutcome)->Result<(),OriginalTurnFailure>{close_original_retained_step(cx,d,advance).map(|_|())}
/// 🛫️ Closes one cursor that needs the original retirement decoder next to its performed-work effect.
fn retire_native(cx:&mut StepContext<'_>,d:RetirementDemand,advance:impl FnOnce(&mut Native<'_,'_>,&mut RetainedAllocationEffect<'_>)->OriginalRetirementPoll)->Result<(),OriginalTurnFailure>{
 if cx.retirement_should_yield()||!fits(cx,d){return Ok(())}
 let grant=RetainedCloneGrant{maximum_items:1,..cx.retained_grant()};
 let Some((polled,performed))=cx.with_original_effect(grant,|cx,effect|cx.with_native_retirement(|native|Ok::<_,ValueError>(advance(native,effect))))? else{return Ok(())};
 let turn=match polled?{RetainedWorkPoll::Pending{work}=>RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work},RetainedWorkPoll::Complete(turn)=>turn};
 if performed>turn.work{return Err(invalid("original Window effect close performed more work than it settled").into())}
 receive_original_retained_work(cx,turn).map(|_|())
}
/// 📬️ Settles one finished receiving scope: its accepted physical spend is its receipt.
fn settled<R>(cx:&mut StepContext<'_>,scope:Option<OriginalNativeReceivingOutcome>,stepped:Option<Result<Option<R>,ValueError>>)->Result<Option<R>,OriginalTurnFailure>{
 let scope=scope.ok_or_else(||invalid("original Window receiving scope vanished"))?;cx.settle_receiving_scope()?;
 if scope.source_refusal.is_some()||scope.call.is_err(){return Err(ValueError::literal(ValueRefusalKind::InvalidValue,"original Window receiving scope refused").with_retained_progress(scope.retained_progress()).into())}
 Ok(stepped.ok_or_else(||invalid("original Window receiving step vanished"))??)
}
/// 🪡️ Runs one receiving action whose native work the decoder commits itself.
fn received<R>(cx:&mut StepContext<'_>,run:impl FnOnce(&mut NativeDecodeControl<'_>,RetainedCloneGrant)->Result<R,ValueError>)->Result<Option<R>,OriginalTurnFailure>{
 if cx.should_yield(){return Ok(None)}
 let(mut scope,mut stepped,mut committed)=(None,None,0);
 if !cx.with_native_receiving(&mut scope,|native,grant|{let before=native.actual_work();stepped=Some(run(native,grant).map(Some));committed=native.actual_work().saturating_sub(before);Ok(())})?{return Ok(None)}
 cx.consume_fuel(u64::try_from(committed).unwrap_or(u64::MAX));settled(cx,scope,stepped)
}
/// 🪙️ Runs one allocating receiving action inside the decoder's own performed-work effect.
fn effected<R>(cx:&mut StepContext<'_>,d:RetirementDemand,run:impl FnOnce(&mut NativeDecodeControl<'_>,&mut RetainedAllocationEffect<'_>)->Result<R,ValueError>)->Result<Option<R>,OriginalTurnFailure>{
 if !fits(cx,d){return Ok(None)}let work=cx.fuel_remaining();
 received(cx,|native,_|Ok(match native.with_allocated_effect(d,work,|native,effect|run(native,effect))?{Some(result)=>Some(result?),None=>None})).map(Option::flatten)
}
/// 🧾️ A construction step quotes its demand, runs against the decoder and posts its complete physical receipt.
fn native_step<T>(cx:&mut StepContext<'_>,run:impl FnOnce(&mut NativeDecodeControl<'_>)->NativeConstructionStepOutcome<T,OriginalReceivingPrimary>)->Result<(),OriginalTurnFailure>{
 let mut scope:Option<OriginalNativeReceivingOutcome>=None;let mut stepped=None;
 if !cx.with_native_receiving(&mut scope,|native,_|{let outcome=run(native);let p=outcome.progress;let work=outcome.work;let result=NativeConstructionStepOutcome{result:outcome.result.map(|result|result.map(|_|RetainedCloneStep::Progress(p))),receipt_refusal:outcome.receipt_refusal,progress:p,work}.into_step_outcome().result;stepped=Some(RetainedWorkOutcome{result,work});Ok(())})?{return Ok(())}
 let scope=scope.ok_or_else(||invalid("original Window receiving scope vanished"))?;
 if scope.source_refusal.is_some()||scope.call.is_err(){return Err(ValueError::literal(ValueRefusalKind::InvalidValue,"original Window receiving scope refused").with_retained_progress(scope.retained_progress()).into())}
 let turn=stepped.ok_or_else(||invalid("original Window receiving step vanished"))?;
 let turn=RetainedWorkOutcome{work:turn.work,result:turn.result.map_err(|failure|match failure.primary{Some(primary)=>OriginalTurnPrimary::Receiving(primary),None=>OriginalTurnPrimary::Value(failure.receipt_refusal.unwrap_or_else(||invalid("original Window receiving step failed without a cause")).with_retained_progress(failure.progress))})};
 receive_original_receiving_work(cx,turn).map(|_|())
}
fn receive(cx:&mut StepContext<'_>,d:RetirementDemand,run:impl FnOnce(&mut NativeDecodeControl<'_>,RetainedCloneGrant)->Result<RetainedCloneProgress,ValueError>)->Result<(),OriginalTurnFailure>{
 if cx.should_yield()||!fits(cx,d){return Ok(())}
 native_step(cx,|native|native.receive_construction_step_typed::<RetainedCloneProgress,OriginalReceivingPrimary>(d,|native,grant|{let result=run(native,grant);let progress=result.as_ref().map_or_else(|error|error.retained_progress(),|progress|*progress);NativeConstructionStepResult{result:result.map_err(OriginalReceivingPrimary::from),progress,work:1}}))
}
/// 🧾️ Runs one construction step with a progress-shaped body and posts its complete receipt.
pub fn receive_progress(cx:&mut StepContext<'_>,d:RetirementDemand,run:impl FnOnce(&mut NativeDecodeControl<'_>,RetainedCloneGrant)->Result<RetainedCloneProgress,ValueError>)->Result<(),OriginalTurnFailure>{receive(cx,d,run)}
fn primary(failure:OriginalReceivingPrimary)->ValueError{failure.primary.or(failure.quote_refusal).or(failure.allocation_refusal).unwrap_or_else(||invalid("original Window receiver refused without a cause"))}
fn refused(failure:NativeReceivingFailure)->ValueError{let progress=failure.retained_progress();match failure{
 NativeReceivingFailure::Primary(failure)=>primary(failure),
 NativeReceivingFailure::ValueEffect(effect)=>effect.child.or(effect.producer_refusal).or(effect.work_refusal).unwrap_or_else(||primary(effect.receiving)),
 NativeReceivingFailure::RetirementEffect(effect)=>effect.child.map(OriginalRetirementFailure::into_value_error).or(effect.producer_refusal).or(effect.work_refusal).unwrap_or_else(||primary(effect.receiving)),
 NativeReceivingFailure::ReceivingEffect(effect)=>effect.child.map(primary).or(effect.producer_refusal).or(effect.work_refusal).unwrap_or_else(||primary(effect.receiving))
}.with_retained_progress(progress)}
/// ♻️ Moves one owner into its controlled retirement, closes it and drops its empty frame.
fn close_owned<T:RetireOwned>(cx:&mut StepContext<'_>,slot:&mut Option<T>,owner:&mut Option<ControlledRetirement<T>>)->Result<(),OriginalTurnFailure>{
 if owner.as_ref().is_some_and(ControlledRetirement::terminal_is_empty){retire_unit(cx,header::<Option<ControlledRetirement<T>>>(),||{*owner=None;Ok(())})}
 else if let Some(open)=owner.as_mut(){let d=open.selected_demand(4096)?;retire(cx,d,|effect|open.step(4096,effect))}
 else if slot.is_some(){retire_unit(cx,header::<(T,Option<ControlledRetirement<T>>)>(),||match ControlledRetirement::new(slot.take().unwrap()){Ok(open)=>{*owner=Some(open);Ok(())},Err((error,original))=>{*slot=Some(original);Err(error)}})}
 else{Ok(())}
}
/// 🪙️ Runs one allocation-free same-turn unit and posts its receipt and one work unit once; `false` means nothing ran.
pub fn direct_unit(cx:&mut StepContext<'_>,d:RetirementDemand,run:impl FnOnce(RetainedCloneGrant)->Result<RetainedCloneProgress,ValueError>)->Result<bool,OriginalTurnFailure>{
 cx.original_source_parent()?;
 if d.capacity_bytes!=0||cx.should_yield()||cx.fuel_remaining()==0||cx.retained_grant().maximum_items==0||!fits(cx,d){return Ok(false)}
 let progress=run(cx.retained_grant())?;cx.consume_retained(progress)?;cx.consume_fuel(1);Ok(true)
}
/// 🏗️ One caller-resident construction frame, its unplaced unit output and every retained refusal survive across turns.
#[derive(Default)]
pub struct Construction{admission:OriginalConstructionAdmission,refusal:Option<OriginalConstructionFailure>,refusal_close:Option<ControlledRetirement<OriginalConstructionFailure>>,unit:Option<()>,resume:bool}
impl Construction{
 pub fn resume(&self)->bool{self.resume}
 pub fn refused(&self)->bool{self.refusal.is_some()||self.refusal_close.is_some()}
 pub fn terminal_is_empty(&self)->bool{self.admission.terminal_is_empty()&&self.refusal.is_none()&&self.refusal_close.is_none()&&self.unit.is_none()&&!self.resume}
 /// 🏗️ Runs one same-turn construction; `true` means its output is placed and its attempt is reset.
 pub fn run<O>(&mut self,cx:&mut StepContext<'_>,output:&mut Option<O>,d:RetirementDemand,construct:impl FnOnce(RetainedCloneGrant,&mut Option<usize>)->Result<(O,RetainedCloneProgress),ValueError>)->Result<bool,OriginalTurnFailure>{
  if self.refused(){return Err(invalid("original Window construction was refused").into())}
  let resume=&mut self.resume;
  let status=admit_original_construction(cx,output,&mut self.admission,physical(d),1,|scope,actual|{*resume=true;let grant=scope.retained_grant();let result=construct(grant,actual).map(|(value,progress)|{if actual.is_none()&&progress.retained_capacity_bytes!=0{*actual=Some(progress.retained_capacity_bytes)}(value,progress)});RetainedWorkOutcome{result,work:1}})?;
  match status{
   OriginalConstructionStatus::Ready=>{let reset=self.admission.reset_step(cx)?;if reset{self.resume=false}Ok(reset)}
   OriginalConstructionStatus::Pending=>Ok(false),
   OriginalConstructionStatus::Failed=>{if !self.admission.take_failure_into_step(&mut self.refusal,cx)?{return Ok(false)}self.resume=false;Err(invalid("original Window construction was refused").into())}
  }
 }
 pub fn run_unit(&mut self,cx:&mut StepContext<'_>,d:RetirementDemand,construct:impl FnOnce(RetainedCloneGrant,&mut Option<usize>)->Result<((),RetainedCloneProgress),ValueError>)->Result<bool,OriginalTurnFailure>{
  let mut unit=self.unit.take();let done=self.run(cx,&mut unit,d,construct);self.unit=if matches!(done,Ok(true)){None}else{unit};done
 }
 /// 🔁️ Finishes a construction whose constructor already ran; its output was placed before the first resume.
 pub fn settle(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.run_unit(cx,RetirementDemand::default(),|_,_|Err(invalid("original Window construction resumed without its constructor")))}
 /// ♻️ Settles a pending attempt, retires its refusal and releases the frame.
 pub fn close(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{
  if self.resume{if let Err(error)=self.settle(cx){if self.refusal.is_none(){return Err(error)}}return Ok(false)}
  if self.refused(){close_owned(cx,&mut self.refusal,&mut self.refusal_close)?;return Ok(false)}
  if self.admission.take_failure_into_step(&mut self.refusal,cx)?{return Ok(false)}
  if !self.admission.terminal_is_empty(){self.admission.close_step(cx)?;return Ok(false)}
  Ok(true)
 }
}
/// 🎟️ The caller keeps this resident from the first actor lease until the Window load is born and settled.
#[derive(Default)]
pub struct WindowConfigLoadAdmission{construction:Construction,actor:Option<protocol::ActorId>,actor_close:Option<ControlledRetirement<protocol::ActorId>>,settled:bool}
impl WindowConfigLoadAdmission{
 pub fn terminal_is_empty(&self)->bool{self.construction.terminal_is_empty()&&self.actor.is_none()&&self.actor_close.is_none()}
 pub fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{
  if self.actor.is_some()||self.actor_close.is_some(){close_owned(cx,&mut self.actor,&mut self.actor_close)?;return Ok(false)}
  let closed=self.construction.close(cx)?;if closed{self.settled=false}Ok(closed)
 }
}
