fn close_fold(cx:&mut StepContext<'_>,job:&mut FoldJob,d:RetirementDemand)->Result<(),OriginalTurnFailure>{
 cx.with_native_retirement(|native|Ok::<_,ValueError>(job.validate_original(native)))??;
 retire(cx,d,|effect|job.close_step(4096,effect))
}
fn pair_failure_demand()->RetirementDemand{header::<(OriginalArtifactPairFailure,Option<OriginalArtifactPairFailure>)>()}
fn pair_body(cx:&StepContext<'_>)->Option<usize>{cx.retained_grant().maximum_copy_bytes.checked_sub(pair_failure_demand().copy_bytes).filter(|body|*body>0).map(|body|body.min(4096))}
fn pair_child_grant(mut grant:RetainedCloneGrant)->RetainedCloneGrant{grant.maximum_copy_bytes-=pair_failure_demand().copy_bytes;grant}
fn pair_error(slot:&mut Option<OriginalArtifactPairFailure>,error:OriginalArtifactPairFailure)->ValueError{
 assert!(slot.is_none(),"complete pair failure destination must be vacant before its producer runs");let mut progress=error.progress;progress.copied_bytes=progress.copied_bytes.checked_add(pair_failure_demand().copy_bytes).expect("prequoted pair failure copy fits");*slot=Some(error);invalid("original Window Pack/SPR receiving refused; complete cause remains retained").with_retained_progress(progress)
}
fn pair_demand(cx:&mut StepContext<'_>,slot:&mut Option<OriginalArtifactPairFailure>,query:impl FnOnce(&mut dyn NativeDecodeCloseControl)->Result<RetirementDemand,OriginalArtifactPairFailure>)->Result<Option<RetirementDemand>,OriginalTurnFailure>{
 if cx.retirement_should_yield()||slot.is_some()||!fits(cx,pair_failure_demand()){return Ok(None)}
 match cx.with_native_retirement(|native|Ok::<_,ValueError>(query(native)))?{Ok(demand)=>{let mut total=demand;total.copy_bytes=total.copy_bytes.checked_add(pair_failure_demand().copy_bytes).ok_or_else(||invalid("pair failure capture quote overflow"))?;Ok(fits(cx,total).then_some(demand))},Err(error)=>{let diagnostic=pair_error(slot,error);cx.consume_retained(diagnostic.retained_progress())?;cx.consume_fuel(1);Err(diagnostic.into())}}
}
/// 🧾️ A stored pair failure pays its prequoted capture copy once after the action that produced it.
fn captured(cx:&mut StepContext<'_>,fault:&Option<OriginalArtifactPairFailure>,ran:Result<(),OriginalTurnFailure>)->Result<(),OriginalTurnFailure>{
 let posted=if fault.is_some(){cx.consume_retained(RetainedCloneProgress{copied_bytes:pair_failure_demand().copy_bytes,..Default::default()})}else{Ok(())};ran?;Ok(posted?)
}
